#include <stdio.h>
#include <stdlib.h>
#include <sys/shm.h>
#include <sys/ipc.h>
#include <errno.h>

#define SEGMENT_KEY 0x12345
#define SEGMENT_SIZE 4096

int main() {
    int shmid;
    struct shmid_ds shm_info;

    // 1. Create a shared memory segment
    shmid = shmget(SEGMENT_KEY, SEGMENT_SIZE, IPC_CREAT | 0600);
    if (shmid == -1) {
        perror("shmget failed");
        return EXIT_FAILURE;
    }
    printf("Created segment ID: %d\n", shmid);

    // 2. Control operation: Retrieve segment status (IPC_STAT)
    if (shmctl(shmid, IPC_STAT, &shm_info) == -1) {
        perror("shmctl IPC_STAT failed");
        // Attempting to remove the segment if stat fails, for cleanup
        shmctl(shmid, IPC_RMID, NULL);
        return EXIT_FAILURE;
    }
    printf("Segment size retrieved: %zu bytes\n", shm_info.shm_segsz);

    // 3. Control operation: Mark segment for removal (IPC_RMID)
    // The segment will be destroyed when all attached processes detach.
    if (shmctl(shmid, IPC_RMID, NULL) == -1) {
        perror("shmctl IPC_RMID failed");
        return EXIT_FAILURE;
    }
    printf("Segment marked for destruction.\n");

    return EXIT_SUCCESS;
}
